<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\DriverService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('DRIVER_REVIEW_QUEUE_VIEW');$id=(int)($_GET['id']??0);$errors=[];$d=DriverService::review($id);if(!$d){http_response_code(404);exit('Driver verification not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{DriverService::decide($id,(int)Auth::user()['id'],(string)($_POST['decision']??''),(string)($_POST['reason']??''));header('Location: '.Url::to('operations/drivers.php?saved=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$today=gmdate('Y-m-d');$compliant=$d['setup_used_at']&&$d['engagement_status']==='carrier_approved'&&$d['medical_result']==='FIT'&&$d['licence_expiry']>=$today&&$d['medical_expiry']>=$today;$pageTitle='Driver Verification';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($d['display_name'])?></h1><p><?=h($d['carrier_company_name']?:$d['carrier_user_name'])?></p></div><span class="badge"><?=h($d['case_status'])?></span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="<?=h($compliant?'success':'error')?>"><strong>Verification precheck: <?=h($compliant?'PASS':'FAIL')?></strong><br>Approval requires completed password setup, Carrier approval, FIT medical status, and unexpired licence and medical references.</div><div class="grid"><div class="card"><h3>Identity</h3><p><?=h($d['identity_type'].' · '.$d['identity_number'].' · '.$d['identity_country'])?></p></div><div class="card"><h3>Licence</h3><p><?=h($d['licence_number'].' · '.$d['licence_country'])?></p><p><?=h($d['licence_categories'].' · expires '.$d['licence_expiry'])?></p></div><div class="card"><h3>Medical</h3><p><?=h($d['medical_certificate_number'].' · '.$d['medical_result'])?></p><p><?=h($d['medical_exam_date'].' – '.$d['medical_expiry'])?></p></div></div><?php if($d['case_status']==='pending'):?><div class="decision-grid" style="margin-top:18px"><?php if(Auth::can('DRIVER_REVIEW_APPROVE')):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="decision" value="approved"><textarea name="reason" maxlength="2000" rows="4" placeholder="Approval note (optional)"></textarea><button class="button" style="margin-top:12px" <?=$compliant?'':'disabled'?>>Verify and activate Driver</button></form><?php endif;?><?php if(Auth::can('DRIVER_REVIEW_REJECT')):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="decision" value="rejected"><textarea name="reason" minlength="10" maxlength="4000" rows="4" placeholder="Rejection reason" required></textarea><button class="button danger" style="margin-top:12px">Reject Driver</button></form><?php endif;?></div><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
